// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto as C} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n) public {
        // n: number of play() calls, between 1 and 100
        n = uint8(bound(n, 1, 100));
        address player = address(0x100);
        vm.deal(player, 10 * uint256(n));
        vm.startPrank(player);
        for (uint8 i = 0; i < n; i++) {
            c.play{value: 10}();
        }
        vm.stopPrank();
        // Invariant: contract balance == pot (no ether held elsewhere)
        assertEq(address(c).balance, c.pot());
    }
}
